const out = [];
const items = $input.all();

const originalFileName = $('Telegram Trigger').first().json.message.document.file_name;
const source = originalFileName;

for (let i = 0; i < items.length; i++) {
  const binaryPropertyName = Object.keys(items[i].binary)[0] || 'data';
  const text = (await this.helpers.getBinaryDataBuffer(i, binaryPropertyName)).toString('utf8');

  let skip = false, category = '';

  for (const raw of text.split(/\r?\n(?=#{2,4} )/)) {
    const part = raw.replace(/^---\s*$/gm, '').trim();
    const heading = part.split('\n')[0];

    if (/^## /.test(heading)) {
      skip = /ASSISTANT/i.test(heading);
      category = '';
      continue;
    }

    if (!/^#{3,4} /.test(heading)) continue;
    if (skip) continue;

    if (/^### Category:/.test(heading)) {
      category = heading.replace(/^#+\s*Category:\s*/, '');
      continue;
    }

    if (part.split('\n').length < 2) continue;

    const title = heading.replace(/^#+\s*/, '');
    const m = heading.match(/FAQ-\d+/) ||
              part.match(/\*\*(?:Event|Workshop|Department) ID:\*\* (\S+)/);

    out.push({
      json: {
        text: part,
        source,
        id: m ? (m[1] || m[0]) : null,
        title,
        category
      }
    });
  }
}

return out;
